import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nothingness/controllers/library_controller.dart';
import 'package:nothingness/models/audio_track.dart';
import 'package:nothingness/models/song_info.dart';
import 'package:nothingness/services/library_browser.dart';
import 'package:nothingness/services/library_service.dart';
import 'package:nothingness/services/playback_controller.dart';
import 'package:nothingness/services/settings_service.dart';
import 'package:nothingness/theme/themes.dart';
import 'package:nothingness/widgets/void_browser.dart';
import 'package:provider/provider.dart';

import '../heroes/_test_helpers.dart';

class _RecordingLibraryController extends LibraryController {
  _RecordingLibraryController({
    required super.libraryBrowser,
    required super.libraryService,
    required this.currentPath,
    required this.tracks,
  }) : super(isAndroidOverride: false) {
    hasPermission = true;
  }

  @override
  bool get isAndroid => false;

  @override
  Future<void> loadFolder(String path) async {}

  @override
  String? currentPath;

  @override
  List<AudioTrack> tracks;

  @override
  List? get folders => const [];
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(() {
    // Keep SettingsService in a deterministic baseline; VoidBrowser reads
    // smartFoldersPresentationNotifier.
    SettingsService().smartFoldersPresentationNotifier.value = true;
  });

  testWidgets(
    'Linux-only scroll action appears when the playing row is off-screen, '
    'and activates without changing the current folder.',
    (tester) async {
      final currentPath = '/lib/Music';
      final tracks = List<AudioTrack>.generate(
        10,
        (i) => AudioTrack(
          path: '$currentPath/track_$i.mp3',
          title: 'Track $i',
        ),
      );
      final playingPath = tracks.last.path;

      final libraryController = _RecordingLibraryController(
        libraryBrowser: LibraryBrowser(supportedExtensions: const {'mp3'}),
        libraryService: LibraryService(),
        currentPath: currentPath,
        tracks: tracks,
      );

      final playback = FakeAudioPlayerProvider(
        songInfo: SongInfo(
          track: AudioTrack(path: playingPath, title: 'Track 9'),
          isPlaying: true,
          position: 0,
          duration: 1000,
        ),
        isPlaying: true,
      );

      await tester.pumpWidget(
        wrapWithProvider(
          playback,
          ChangeNotifierProvider<LibraryController>.value(
            value: libraryController,
            child: SizedBox(
              width: 400,
              height: 160, // small viewport → last row is off-screen
              child: VoidBrowser(controller: libraryController),
            ),
          ),
        ),
      );
      await tester.pump();

      const actionKey = ValueKey('void-browser-jump-to-now-playing');
      expect(find.byKey(actionKey), findsOneWidget);

      expect(
        find.byKey(ValueKey('void-file:$playingPath')),
        findsNothing,
        reason: 'precondition — last track row must be off-screen',
      );

      await tester.tap(find.byKey(actionKey));
      await tester.pumpAndSettle(const Duration(milliseconds: 500));

      expect(
        find.byKey(ValueKey('void-file:$playingPath')),
        findsOneWidget,
        reason: 'after activation — playing row must be visible',
      );

      expect(
        find.byKey(actionKey),
        findsNothing,
        reason: 'action must be hidden once the row is visible',
      );

      expect(libraryController.currentPath, currentPath,
          reason: 'activation must keep the browser folder unchanged');
    },
  );

  testWidgets(
    'does not expose the action when no track is playing',
    (tester) async {
      final currentPath = '/lib/Music';
      final tracks = List<AudioTrack>.generate(
        10,
        (i) => AudioTrack(
          path: '$currentPath/track_$i.mp3',
          title: 'Track $i',
        ),
      );

      final libraryController = _RecordingLibraryController(
        libraryBrowser: LibraryBrowser(supportedExtensions: const {'mp3'}),
        libraryService: LibraryService(),
        currentPath: currentPath,
        tracks: tracks,
      );

      final playback = FakeAudioPlayerProvider(
        songInfo: SongInfo(
          track: tracks.last,
          isPlaying: false,
          position: 0,
          duration: 1000,
        ),
        isPlaying: false,
      );

      await tester.pumpWidget(
        wrapWithProvider(
          playback,
          ChangeNotifierProvider<LibraryController>.value(
            value: libraryController,
            child: SizedBox(
              width: 400,
              height: 160,
              child: VoidBrowser(controller: libraryController),
            ),
          ),
        ),
      );
      await tester.pump();

      const actionKey = ValueKey('void-browser-jump-to-now-playing');
      expect(find.byKey(actionKey), findsNothing);
    },
  );
}

